  "«Аккаунтты өшіру» — аккаунт, еске салулар және бот жазбалары бірден, толық өшеді; журналда тек атсыз «аккаунт өшірілді» жазбасы қалады": "“Delete account” — account, reminders, and bot records are deleted immediately and fully; only anonymized “account deleted” remains in log",
