  "«Жоқ» десеңіз, бетте тек жүйе растаған жазбалар болады. Кейін кез келген уақытта өзгертуге болады. GPA, телефон және email жіберілмейді.": "If “No”, only system-confirmed records show on page. You can change this anytime. GPA, phone, and email are not sent.",
  "«Маған сай» тізімі сіздің хабарландыруыңызға қарап құралады.": "“Fits me” list is based on your ad.",
  "«Пәтерлес» тек кірген студенттерге ашық: хабарландыруда аты-жөн мен байланыс жоқ, олар екі жақ келіскенде ғана ашылады.": "“Roommates” open only to logged-in students: ads have no names or contacts, revealed only by mutual consent.",
