  "Агрономия факультетінің корпусы, 5 қабат. Кампустың оңтүстік-батысы": "Agronomy faculty building, 5 floors. Southwest campus",
  "Адам алдымен Telegram арқылы кіріп, келісім береді. Содан кейін оны осында университетке байлаңыз — тек рөл беру жеткіліксіз. Қызметкер тек жиынтық сандарды көреді.": "User first signs in via Telegram and consents. Then link them here to the university — role alone is not enough. Staff see only aggregated numbers.",
