  "Академиялық адалдық: емтихан не бақылау кезінде тапсырма жауаптарын жарияламаңыз. Модераторлар мұндай тақырыпты жабады.": "Academic honesty: don’t post answers during exams or tests. Moderators close such topics.",
  "Академиялық анықтама": "Academic transcript",
  "Академиялық тобым": "My academic group",
  "Академиялық ұтқырлық": "Academic mobility",
  "Академиялық ұтқырлық бағдарламалары": "Academic mobility programs",
  "Академиялық ұтқырлық бөлімі": "Academic mobility department",
  "Академиялық ұтқырлыққа құжаттар": "Documents for academic mobility",
  "Академиялық ұтқырлыққа, тағылымдамаға, шетелдік бағдарламаларға.": "For academic mobility, internships, foreign programs.",
  "Аккаунт": "Account",
  "Аккаунт ашу": "Create account",
  "Аккаунт деректері Student Hub-тың жалға алынған серверіндегі (VPS) дерекқорда сақталады, күн сайын резервтік көшірмесі алынады (7 күн сақталады); сервер елі заңгер тексеруінде нақтыланады. Кіру Telegram не email арқылы өтеді; email кодтары бар хаттар Resend (АҚШ) поштасы арқылы жіберіледі. AI-чатты қолдансаңыз, хабарламаңыз бен профильдің бір бөлігі (мамандық, курс, GPA, ағылшын деңгейі, дағдылар, тәжірибе) жауап алу үшін AI провайдеріне (OpenAI, АҚШ) жіберіледі, бізде сақталмайды. Аналитика анонимді, Student Hub серверінде.": "Account data is stored in Student Hub’s rented server (VPS) database, backed up daily (kept 7 days); server country is verified by legal review. Login via Telegram or email; code emails sent via Resend (USA). Using AI chat sends your message and part of your profile (major, course, GPA, English level, skills, experience) to AI provider (OpenAI, USA) for response; we do not store it. Analytics are anonymous on Student Hub server.",
  "Аккаунт деректерін сіз және Student Hub әкімшілері ғана көреді. Деректер сатылмайды, жарнамаға берілмейді. GPA мен телефон ешкімге көрсетілмейді.": "Only you and Student Hub admins see account data. Data is not sold or used for ads. GPA and phone are never shown.",
  "Аккаунт және деректеріңіз": "Account and your data",
  "Аккаунт керек: келу сізге ғана жазылады.": "Account required: attendance marks only recorded for you.",
  "Аккаунт хабарламалары": "Account messages",
  "Аккаунт өшірілді": "Account deleted",
  "Аккаунт — өзіңіз өшіргенше. Сессия — студентке 90 күн (қолданған сайын ұзарады), қызметкер рөлдеріне 14 күн. Серверде күн сайын дерекқордың резервтік көшірмесі алынады, көшірме 7 күн сақталады. Аналитиканың сақталу мерзімі әлі белгіленбеген және заңгер тексеруінен кейін нақтыланады.": "Account lasts until you delete it. Session: 90 days for students (extends with use), 14 days for staff roles. Daily database backups stored 7 days. Analytics retention period not set; will be confirmed after legal review.",
  "Аккаунтпен синхрондалды": "Synced with account",
  "Аккаунтпен синхрондау": "Sync with account",
  "Аккаунтта жоқ — Параметрлер → «Аккаунтпен синхрондау»": "Not in account — Settings → “Sync with account”",
  "Аккаунтта сақталған: {0}. Құрылғыда: {1}.": "Saved in account: {0}. On device: {1}.",
  "Аккаунтты қолдану үшін деректер туралы келісім керек": "Consent to data processing required to use account",
  "Аккаунтты қолдану үшін келісім керек.": "Consent required to use account.",
  "Аккаунтты өшіру": "Delete account",
  "Аккаунттың email-ін жазыңыз. Осы адрес бізде болса, оған код келеді.": "Enter account email. If we have it, a code will be sent there.",
  "Аккаунтыңыз бар ма?": "Already have an account?",
  "Аккаунтқа Telegram байланыспаған, сондықтан бот хабарлама жібере алмайды. Жоғарыдағы «Аккаунт» бөлімінде Telegram-ды байланыстырыңыз.": "Telegram not linked to account, so bot cannot send messages. Link Telegram in the “Account” section above.",
